def _required_local_files(masked_text: str) -> list[str]:
    """Workspace-root .k files pulled in by requires clauses, in order."""

    names: list[str] = []
    for match in re.finditer(r'(?m)^\s*requires\s+"([^"]+)"', masked_text):
        name = match.group(1)
        if "/" in name or not name.endswith(".k"):
            continue
        if name not in names:
            names.append(name)
    return names


def inventory_verification(workspace: Path) -> dict[str, Any]:
    workspace = Path(workspace)
    try:
        workspace_mode = workspace.stat(follow_symlinks=False).st_mode
    except OSError as error:
        raise KRuleInventoryError(
            f"workspace must be a real directory: {workspace}"
        ) from error
    if not stat.S_ISDIR(workspace_mode):
        raise KRuleInventoryError(
            f"workspace must be a real directory: {workspace}"
        )

